#!/usr/bin/env bash
# DISPOSABLE RESEARCH EXPERIMENT. Not product code. Lives only under docs/research/.
# Supports docs/research/2026-09-14-traversal-at-scale.md. Never invoked by product code.
#
# Benchmarks four query shapes (recursive subtree collect, denormalised-field
# subtree collect, dependency closure for a leaf, dependency edges within a
# subtree) against SurrealDB 3.2.3 for synthetic trees of size N, generated by
# 2026-09-14-generate-traversal-data.py in this directory.
#
# Usage: ./2026-09-14-run-traversal-benchmark.sh <out_dir> <n1> [n2 ...]
# Requires: surreal (3.2.3, on PATH), python3, curl. Starts a fresh
# `surreal start memory` instance per size, kills it afterwards. Writes a
# per-size raw-timings file and a summary CSV into <out_dir>.
#
# This script starts and kills local `surreal` server processes. It is meant
# to be run by hand from a scratch directory, not from CI or product tooling.

set -euo pipefail

OUT_DIR="${1:?usage: $0 <out_dir> <n...>}"
shift
SIZES=("$@")
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
GEN="$SCRIPT_DIR/2026-09-14-generate-traversal-data.py"

mkdir -p "$OUT_DIR"
SUMMARY="$OUT_DIR/summary.csv"
echo "n,query,wall_median_ms,wall_max_ms,engine_median_ms,engine_max_ms,rss_mb" > "$SUMMARY"

median() { python3 -c "import sys,statistics; xs=[float(x) for x in sys.argv[1:]]; print(statistics.median(xs))" "$@"; }
maxv()    { python3 -c "import sys; xs=[float(x) for x in sys.argv[1:]]; print(max(xs))" "$@"; }

run_query_5x() {
  # $1 = label, $2 = query file (raw SurrealQL body), writes wall/engine times
  local label="$1" qfile="$2"
  local walls=() engines=()
  for i in 1 2 3 4 5; do
    local resp
    resp=$(curl -s -u root:root -H "surreal-ns: bench" -H "surreal-db: bench" \
      -w '\n%{time_total}' -X POST http://127.0.0.1:8000/sql --data-binary "@$qfile")
    local body wall engine_us
    wall=$(echo "$resp" | tail -n1)
    body=$(echo "$resp" | sed '$d')
    engine_us=$(echo "$body" | python3 -c "
import json,sys
r=json.load(sys.stdin)
last=r[-1]
t=last['time']
# SurrealDB reports durations like '1.965167ms' or '431.667µs' or '2.4s'
import re
m=re.match(r'([0-9.]+)(µs|ms|s)', t)
val=float(m.group(1)); unit=m.group(2)
mult={'µs':0.001,'ms':1.0,'s':1000.0}[unit]
print(val*mult)
")
    walls+=("$(python3 -c "print(${wall}*1000)")")
    engines+=("$engine_us")
    echo "  [$label] run $i: wall=${wall}s engine=${engine_us}ms" >&2
  done
  local wmed wmax emed emax
  wmed=$(median "${walls[@]}"); wmax=$(maxv "${walls[@]}")
  emed=$(median "${engines[@]}"); emax=$(maxv "${engines[@]}")
  echo "$wmed,$wmax,$emed,$emax"
}

for N in "${SIZES[@]}"; do
  echo "=== N=$N ===" >&2
  pkill -f "surreal start" 2>/dev/null || true
  sleep 1
  nohup surreal start --user root --pass root memory > "$OUT_DIR/server_$N.log" 2>&1 &
  SPID=$!
  sleep 2

  DATA="$OUT_DIR/data_$N.surql"
  ERRF="$OUT_DIR/data_$N.stderr"
  python3 "$GEN" --n "$N" --seed 1 > "$DATA" 2> "$ERRF"
  LEAF=$(grep '^leaf=' "$ERRF" | cut -d= -f2)
  echo "leaf=$LEAF" >&2

  echo "  loading data..." >&2
  LOAD_START=$(python3 -c "import time; print(time.time())")
  curl -s -u root:root -H "surreal-ns: bench" -H "surreal-db: bench" \
    -X POST http://127.0.0.1:8000/sql --data-binary "@$DATA" > "$OUT_DIR/load_$N.json"
  LOAD_END=$(python3 -c "import time; print(time.time())")
  python3 -c "print('  load wall seconds:', $LOAD_END - $LOAD_START)" >&2
  if grep -q '"status":"ERR"' "$OUT_DIR/load_$N.json"; then
    echo "  WARNING: some load statements errored, see $OUT_DIR/load_$N.json" >&2
    grep -o '"status":"ERR"[^}]*' "$OUT_DIR/load_$N.json" | head -5 >&2
  fi

  # query files
  QA="$OUT_DIR/qa_$N.surql"
  QB="$OUT_DIR/qb_$N.surql"
  QC="$OUT_DIR/qc_$N.surql"
  QD="$OUT_DIR/qd_$N.surql"
  echo "RETURN task:t0.{1..50+collect}(->contains->task);" > "$QA"
  echo "SELECT id FROM task WHERE root = task:t0;" > "$QB"
  echo "RETURN $LEAF.{1..50+collect}(->depends_on->task);" > "$QC"
  cat > "$QD" <<EOF
LET \$subtree = task:t0.{1..50+collect+inclusive}(->contains->task);
RETURN (SELECT * FROM depends_on WHERE in INSIDE \$subtree AND out INSIDE \$subtree);
EOF

  RA=$(run_query_5x "a-recursive-subtree" "$QA")
  RB=$(run_query_5x "b-denorm-subtree" "$QB")
  RC=$(run_query_5x "c-dep-closure-leaf" "$QC")
  RD=$(run_query_5x "d-deps-in-subtree" "$QD")

  RSS_KB=$(ps -o rss= -p "$SPID" | tr -d ' ')
  RSS_MB=$(python3 -c "print(round(${RSS_KB:-0}/1024, 1))")

  echo "$N,a-recursive-subtree,$RA,$RSS_MB" >> "$SUMMARY"
  echo "$N,b-denorm-subtree,$RB,$RSS_MB" >> "$SUMMARY"
  echo "$N,c-dep-closure-leaf,$RC,$RSS_MB" >> "$SUMMARY"
  echo "$N,d-deps-in-subtree,$RD,$RSS_MB" >> "$SUMMARY"

  kill "$SPID" 2>/dev/null || true
  sleep 1
done

echo "Done. Summary at $SUMMARY" >&2
cat "$SUMMARY"
